from rest_framework import serializers, viewsets, permissions
from django.contrib.auth import get_user_model
from .models import CorporateExpenseClaim

User = get_user_model()

class ExpenseClaimSerializer(serializers.HyperlinkedModelSerializer):
    approver = serializers.HyperlinkedRelatedField(
        view_name='user-detail',
        queryset=User.objects.none()
    )

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        request = self.context.get('request')
        if request and hasattr(request, 'user'):
            user_dept = getattr(request.user, 'department', None)
            if user_dept:
                self.fields['approver'].queryset = user_dept.authorized_approvers.all()

    class Meta:
        model = CorporateExpenseClaim
        fields = ('url', 'id', 'expense_title', 'amount_requested', 'approver')

class ExpenseClaimViewSet(viewsets.ModelViewSet):
    serializer_class = ExpenseClaimSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return CorporateExpenseClaim.objects.filter(claimant=self.request.user)

    def perform_create(self, serializer):
        serializer.save(claimant=self.request.user)
